`
      UPDATE user_rewards SET status='CLAIMED',claimed_at=now(),coupon_code=${couponCode}
      WHERE user_id=${userId} AND reward_definition_id=${rewardDefinitionId}
      RETURNING status,coupon_code AS "couponCode",claimed_at AS "claimedAt"`

`
    SELECT id FROM bet_markets
    WHERE event_id=${eventId} AND (
      normalized_key=${market.normalizedKey}
      OR (
        provider_market_id=${market.providerMarketId}
        AND side=${market.side}
        AND line_key=coalesce(${market.line}::numeric, -999999::numeric)
      )
    )
    LIMIT 1`

`
    UPDATE auth_tokens SET consumed_at = now() WHERE token_hash = ${tokenHash(token)} AND type = ${type}
      AND consumed_at IS NULL AND expires_at > now() RETURNING id, user_id`

`AND (s.headline ILIKE ${`%${query}%`} OR s.summary ILIKE ${`%${query}%`} OR s.what_happened ILIKE ${`%${query}%`} OR EXISTS (
        SELECT 1 FROM story_evidence se JOIN content_sources cs ON cs.id=se.source_id
        WHERE se.story_id=s.id AND cs.name ILIKE ${`%${query}%`}
      ))`

`INSERT INTO commerce_order_items(
          id,order_id,product_id,variant_id,sku,product_name,variant_label,image_url,quantity,
          unit_price_cents,line_total_cents
        ) VALUES(
          ${randomUUID()},${id},${variant.product_id},${variant.id},${variant.sku},
          ${variant.product_name},${variant.color_label ?? variant.size ?? 'Standard'},
          ${variant.image_url},${quantity},${variant.unit_price_cents},
          ${variant.unit_price_cents * quantity}
        )`

`
      INSERT INTO commerce_refunds(
        id,request_id,order_id,stripe_payment_intent_id,amount_cents,currency,status,reason,
        created_by_user_id
      ) VALUES(
        ${randomUUID()},${input.requestId},${order.id},${order.stripe_payment_intent_id},${amount},
        ${order.currency},'PENDING',${input.reason ?? null},${input.adminUserId}
      ) RETURNING *`

`UPDATE commerce_refunds SET status='FAILED',failure_reason=${
      error instanceof Error ? error.message.slice(0, 240) : 'Stripe refund request failed'
    },updated_at=now() WHERE request_id=${input.requestId} AND stripe_refund_id IS NULL`

`SELECT c.id,u.display_name AS "senderName" FROM crews c
    JOIN crew_members m ON m.crew_id=c.id JOIN users u ON u.id=${userId}
    WHERE m.user_id=${userId} AND m.status='ACTIVE' LIMIT 1`

`INSERT INTO crew_reactions(activity_id,user_id,reaction) SELECT ${activityId},${userId},${reaction}
    WHERE EXISTS(SELECT 1 FROM crew_activity a JOIN crew_members m ON m.crew_id=a.crew_id WHERE a.id=${activityId} AND m.user_id=${userId} AND m.status='ACTIVE')
    ON CONFLICT DO NOTHING`

`
    SELECT id,season,week,home_team_id AS "homeTeamId",away_team_id AS "awayTeamId",
      kickoff_at::text AS "kickoffAt" FROM historical_games
    WHERE season=${event.season ?? new Date(event.kickoffAt).getFullYear()}
      AND week=${event.week}
      AND home_team_id=${event.homeTeamId}
      AND away_team_id=${event.awayTeamId}
      AND home_score IS NOT NULL AND away_score IS NOT NULL
    LIMIT 1`
